function buildMobileOfferRecord(item = {}) {
  const currency = normalizeInputValue(item.currency || "EUR") || "EUR";
  const subtotal = Number(item.taxableSubtotal ?? item.subtotal ?? 0) || 0;
  const total = Number(item.total ?? 0) || 0;
  const amountLabel = getCommercialMoneyText(subtotal, currency);
  const totalLabel = getCommercialMoneyText(total, currency);
  return {
    id: normalizeInputValue(item.id),
    title: normalizeInputValue(item.offerNumber || item.externalDocumentNumber || item.title || "Ponuda"),
    subtitle: [
      normalizeInputValue(item.title),
      normalizeInputValue(item.companyName),
      normalizeInputValue(item.locationName || (Array.isArray(item.selectedLocationNames) ? item.selectedLocationNames.join(", ") : "")),
    ].filter(Boolean).join(" - "),
    status: normalizeInputValue(item.status || "draft"),
    kind: "offer",
    date: normalizeInputValue(item.offerDate || item.validUntil || item.updatedAt || item.createdAt),
    relatedId: normalizeInputValue(item.companyId),
    coordinates: "",
    meta: {
      offerNumber: normalizeInputValue(item.offerNumber || item.externalDocumentNumber),
      title: normalizeInputValue(item.title),
      companyName: normalizeInputValue(item.companyName),
      locationName: normalizeInputValue(item.locationName || (Array.isArray(item.selectedLocationNames) ? item.selectedLocationNames.join(", ") : "")),
      contactName: normalizeInputValue(item.contactName),
      contactEmail: normalizeInputValue(item.contactEmail),
      contactPhone: normalizeInputValue(item.contactPhone),
      serviceLine: normalizeInputValue(item.serviceLine),
      offerDate: normalizeInputValue(item.offerDate),
      validUntil: normalizeInputValue(item.validUntil),
      amountWithoutVat: amountLabel,
      totalWithVat: totalLabel,
      currency,
    },
  };
}

function resolveVehicleUsageMode(value = "") {
  const normalized = normalizeInputValue(value).toLowerCase();
  if (["return", "checkin", "check_in", "vracanje", "povrat"].includes(normalized)) {
    return "return";
  }
  if (["checkout", "check_out", "preuzimanje", "start"].includes(normalized)) {
    return "checkout";
  }
  return "usage";
}

function getVehicleUsagePerformerLabel(user = {}, body = {}) {
  return normalizeInputValue(
    body.performedBy
    || body.reservedForLabel
    || user.fullName
    || user.displayName
    || user.username
    || user.email
    || "Korisnik",
  );
}

function getVehicleUsageDriverLabels(user = {}, body = {}, reservation = null) {
  const explicitLabels = Array.isArray(body.driverLabels)
    ? body.driverLabels
    : Array.isArray(body.drivers)
      ? body.drivers
      : [];
  const reservationLabels = Array.isArray(reservation?.reservedForLabels)
    ? reservation.reservedForLabels
    : [reservation?.reservedForLabel];
  const labels = [
    ...explicitLabels,
    body.driverLabel,
    body.driver,
    getVehicleUsagePerformerLabel(user, body),
    ...reservationLabels,
  ]
    .map((value) => normalizeInputValue(value))
    .filter(Boolean);
  return Array.from(new Set(labels));
}

function isVehicleTripActivity(item = {}) {
  const activityType = normalizeInputValue(item?.activityType ?? item?.type).toLowerCase();
  return activityType === "vehicle_trip"
    || Boolean(
      normalizeInputValue(item?.departureAt)
      || normalizeInputValue(item?.returnAt)
      || normalizeInputValue(item?.startKm)
      || normalizeInputValue(item?.endKm)
      || normalizeInputValue(item?.tripStatus),
    );
}

function getVehicleUsageDestination(body = {}, reservation = null, existingTrip = null) {
  return normalizeInputValue(
    body.destination
    || body.route
    || body.location
    || existingTrip?.destination
    || reservation?.destination
    || reservation?.purpose,
  );
}

function buildVehicleUsageCondition(body = {}, mode = "checkout") {
  const explicitCondition = normalizeInputValue(body.vehicleCondition || body.condition);
  const checklist = [
    body.vehicleClean !== undefined ? `Vozilo cisto: ${body.vehicleClean ? "da" : "ne"}` : "",
    body.documentsPresent !== undefined ? `Dokumenti u vozilu: ${body.documentsPresent ? "da" : "ne"}` : "",
    body.fuelOk !== undefined ? `Gorivo / baterija uredno: ${body.fuelOk ? "da" : "ne"}` : "",
    body.damageNoted !== undefined ? `Ostecenje evidentirano: ${body.damageNoted ? "da" : "ne"}` : "",
    normalizeInputValue(body.note),
  ].map(normalizeInputValue).filter(Boolean);
  const fallbackPrefix = mode === "return" ? "Povrat" : "Polazak";
  return [
    explicitCondition,
    checklist.length ? `${fallbackPrefix}: ${checklist.join("; ")}` : "",
  ].filter(Boolean).join("\n");
}

function findOpenVehicleTrip(vehicle = {}, body = {}, reservation = null) {
  const requestedTripId = normalizeInputValue(body.tripId || body.activityItemId);
  const requestedReservationId = normalizeInputValue(body.reservationId || reservation?.id);
  const activityItems = Array.isArray(vehicle.activityItems) ? vehicle.activityItems : [];
  const tripItems = activityItems.filter(isVehicleTripActivity);

  if (requestedTripId) {
    const byId = tripItems.find((item) => String(item.id) === requestedTripId);
    if (byId) return byId;
  }

  if (requestedReservationId) {
    const byReservation = tripItems.find((item) => (
      normalizeInputValue(item?.reservationId) === requestedReservationId
      && normalizeInputValue(item?.tripStatus).toLowerCase() !== "completed"
      && !normalizeInputValue(item?.returnAt)
    ));
    if (byReservation) return byReservation;
  }

  return tripItems
    .filter((item) => normalizeInputValue(item?.tripStatus).toLowerCase() !== "completed" && !normalizeInputValue(item?.returnAt))
    .sort((left, right) => (
      normalizeInputValue(right?.departureAt || right?.createdAt || right?.performedOn)
        .localeCompare(normalizeInputValue(left?.departureAt || left?.createdAt || left?.performedOn))
    ))[0] || null;
}

function findVehicleUsageReservation(vehicle = {}, body = {}, mode = "usage", nowValue = new Date().toISOString()) {
  const reservations = Array.isArray(vehicle?.reservations) ? vehicle.reservations : [];
  const requestedId = normalizeInputValue(body.reservationId);
  if (requestedId) {
    return reservations.find((reservation) => String(reservation.id) === requestedId) || null;
  }

  const nowTimestamp = Date.parse(nowValue);
  const activeStatuses = new Set(["reserved", "checked_out"]);
  const sorted = sortVehicleReservations(reservations, nowValue)
    .filter((reservation) => activeStatuses.has(normalizeInputValue(reservation?.status).toLowerCase()));

  if (mode === "return") {
    return sorted.find((reservation) => normalizeInputValue(reservation?.status).toLowerCase() === "checked_out")
      || sorted.find((reservation) => {
        const start = Date.parse(reservation?.startAt ?? "");
        const end = Date.parse(reservation?.endAt ?? "");
        return Number.isFinite(start) && Number.isFinite(end) && start <= nowTimestamp && end >= nowTimestamp;
      })
      || sorted[0]
      || null;
  }

  return sorted.find((reservation) => {
    const start = Date.parse(reservation?.startAt ?? "");
    const end = Date.parse(reservation?.endAt ?? "");
    return Number.isFinite(start) && Number.isFinite(end) && start <= nowTimestamp && end >= nowTimestamp;
  })
    || sorted.find((reservation) => Date.parse(reservation?.startAt ?? "") >= nowTimestamp)
    || sorted[0]
    || null;
}

function buildVehicleUsagePatchLegacy(vehicle = {}, body = {}, user = {}) {
  const nowValue = new Date().toISOString();
  const mode = resolveVehicleUsageMode(body.mode || body.usageMode);
  const odometerKm = normalizeInputValue(body.odometerKm || body.endKm || body.startKm);
  if (!odometerKm) {
    throw new Error("Upiši kilometražu vozila.");
  }

  const performer = getVehicleUsagePerformerLabel(user, body);
  const targetReservation = findVehicleUsageReservation(vehicle, body, mode, nowValue);
  const actionLabel = mode === "return"
    ? "Povrat vozila"
    : mode === "checkout"
      ? "Preuzimanje vozila"
      : "Korištenje vozila";
  const checklist = [
    body.destination ? `Destinacija: ${normalizeInputValue(body.destination)}` : "",
    body.vehicleClean !== undefined ? `Vozilo čisto: ${body.vehicleClean ? "da" : "ne"}` : "",
    body.documentsPresent !== undefined ? `Dokumenti u vozilu: ${body.documentsPresent ? "da" : "ne"}` : "",
    body.fuelOk !== undefined ? `Gorivo / baterija uredno: ${body.fuelOk ? "da" : "ne"}` : "",
    body.damageNoted !== undefined ? `Oštećenje evidentirano: ${body.damageNoted ? "da" : "ne"}` : "",
    normalizeInputValue(body.note),
  ].map(normalizeInputValue).filter(Boolean);

  const activityItem = {
    id: randomUUID(),
    activityType: "usage",
    performedOn: nowValue.slice(0, 10),
    performedBy: performer,
    odometerKm,
    workSummary: actionLabel,
    note: checklist.join("\n"),
    createdAt: nowValue,
    updatedAt: nowValue,
  };
  const patch = {
    odometerKm,
    activityItems: [
      activityItem,
      ...(Array.isArray(vehicle.activityItems) ? vehicle.activityItems : []),
    ],
  };

  if (targetReservation && mode !== "usage") {
    const nextStatus = mode === "return" ? "completed" : "checked_out";
    patch.reservations = (Array.isArray(vehicle.reservations) ? vehicle.reservations : []).map((reservation) => (
      String(reservation.id) === String(targetReservation.id)
        ? {
          ...reservation,
          status: nextStatus,
          note: [
            normalizeInputValue(reservation.note),
            `${actionLabel}: ${odometerKm} km`,
          ].filter(Boolean).join("\n"),
          updatedAt: nowValue,
        }
        : reservation
    ));
  }

  return patch;
}

function buildVehicleUsagePatch(vehicle = {}, body = {}, user = {}) {
  const nowValue = new Date().toISOString();
  const mode = resolveVehicleUsageMode(body.mode || body.usageMode);
  const odometerKm = normalizeInputValue(body.odometerKm || body.endKm || body.startKm);
  if (!odometerKm) {
    throw new Error("Upisi kilometrazu vozila.");
  }

  const targetReservation = findVehicleUsageReservation(vehicle, body, mode, nowValue);
  const openTrip = mode === "return" ? findOpenVehicleTrip(vehicle, body, targetReservation) : null;
  const performer = getVehicleUsagePerformerLabel(user, body);
  const openTripDriverLabels = Array.isArray(openTrip?.driverLabels)
    ? openTrip.driverLabels.map((value) => normalizeInputValue(value)).filter(Boolean)
    : [];
  const driverLabels = mode === "return" && openTripDriverLabels.length
    ? openTripDriverLabels
    : getVehicleUsageDriverLabels(user, body, targetReservation);
  const destination = getVehicleUsageDestination(body, targetReservation, openTrip);
  const condition = buildVehicleUsageCondition(body, mode);
  const linkedWorkOrderId = normalizeInputValue(body.linkedWorkOrderId || body.workOrderId);
  const linkedWorkOrderNumber = normalizeInputValue(body.linkedWorkOrderNumber || body.workOrderNumber);
  const actionLabel = mode === "return"
    ? "Povrat vozila"
    : mode === "checkout"
      ? "Preuzimanje vozila"
      : "Koristenje vozila";
  const activityItems = Array.isArray(vehicle.activityItems) ? vehicle.activityItems : [];
  const patch = { odometerKm };

  if (mode === "return" && openTrip) {
    patch.activityItems = activityItems.map((item) => (
      String(item.id) === String(openTrip.id)
        ? {
          ...item,
          activityType: "vehicle_trip",
          performedOn: item.performedOn || (item.departureAt || nowValue).slice(0, 10),
          performedBy: driverLabels.join(", ") || performer,
          odometerKm,
          workSummary: "Putovanje vozila",
          reservationId: normalizeInputValue(item.reservationId || targetReservation?.id),
          tripStatus: "completed",
          departureAt: normalizeInputValue(item.departureAt || targetReservation?.startAt || nowValue),
          returnAt: nowValue,
          destination,
          driverLabels,
          startKm: normalizeInputValue(item.startKm || item.odometerKm || ""),
          endKm: odometerKm,
          vehicleCondition: condition || normalizeInputValue(item.vehicleCondition),
          departureCondition: normalizeInputValue(item.departureCondition || item.vehicleCondition),
          returnCondition: condition,
          linkedWorkOrderId: linkedWorkOrderId || normalizeInputValue(item.linkedWorkOrderId || item.workOrderId),
          linkedWorkOrderNumber: linkedWorkOrderNumber || normalizeInputValue(item.linkedWorkOrderNumber || item.workOrderNumber),
          note: normalizeInputValue(item.note),
          createdAt: normalizeInputValue(item.createdAt || nowValue),
          updatedAt: nowValue,
        }
        : item
    ));
  } else {
    const isReturnFallback = mode === "return";
    const activityItem = {
      id: randomUUID(),
      activityType: "vehicle_trip",
      performedOn: nowValue.slice(0, 10),
      performedBy: driverLabels.join(", ") || performer,
      odometerKm,
      workSummary: "Putovanje vozila",
      reservationId: normalizeInputValue(targetReservation?.id),
      tripStatus: isReturnFallback ? "completed" : "open",
      departureAt: isReturnFallback ? normalizeInputValue(targetReservation?.startAt || "") : nowValue,
      returnAt: isReturnFallback ? nowValue : "",
      destination,
      driverLabels,
      startKm: isReturnFallback ? "" : odometerKm,
      endKm: isReturnFallback ? odometerKm : "",
      vehicleCondition: condition,
      departureCondition: isReturnFallback ? "" : condition,
      returnCondition: isReturnFallback ? condition : "",
      linkedWorkOrderId,
      linkedWorkOrderNumber,
      note: normalizeInputValue(body.note),
      createdAt: nowValue,
      updatedAt: nowValue,
    };
    patch.activityItems = [activityItem, ...activityItems];
  }

  if (targetReservation && mode !== "usage") {
    const nextStatus = mode === "return" ? "completed" : "checked_out";
    patch.reservations = (Array.isArray(vehicle.reservations) ? vehicle.reservations : []).map((reservation) => (
      String(reservation.id) === String(targetReservation.id)
        ? {
          ...reservation,
          status: nextStatus,
          note: [
            normalizeInputValue(reservation.note),
            `${actionLabel}: ${odometerKm} km`,
          ].filter(Boolean).join("\n"),
          updatedAt: nowValue,
        }
        : reservation
    ));
  }

  return patch;
}

function getVehicleEvidencePdfFileName(vehicle = {}) {
  return sanitizeGeneratedDocumentFileName(
    `evidencija-vozila-${vehicle.plateNumber || vehicle.name || vehicle.id || "vozilo"}`,
    {
      fallback: "evidencija-vozila",
      extension: "pdf",
    },
  );
}

function buildMobileCalendarEvents(scopedSnapshot = {}, workOrders = []) {
  const events = [];

  workOrders.forEach((workOrder) => {
    const date = firstMobileRecordValue(workOrder, ["executionDate"]);
    if (!date) return;
    events.push({
      id: `work-order:${workOrder.id}`,
      title: workOrder.workOrderNumber || workOrder.number || "Radni nalog",
      subtitle: [workOrder.companyName, workOrder.locationName].filter(Boolean).join(" - "),
      status: workOrder.status,
      kind: "work_order",
      date,
      relatedId: workOrder.id,
      coordinates: workOrder.coordinates,
      meta: {
        companyName: workOrder.companyName,
        locationName: workOrder.locationName,
      },
    });
  });

  (scopedSnapshot.fieldInquiries ?? []).forEach((inquiry) => {
    const date = firstMobileRecordValue(inquiry, ["plannedDate"]);
    if (!date) return;
    const record = buildMobileFieldInquiryRecord(inquiry);
    events.push({
      ...record,
      id: `field-inquiry:${inquiry.id}`,
      kind: "field_inquiry",
    });
  });

  (scopedSnapshot.vehicles ?? []).forEach((vehicle) => {
    (vehicle.reservations ?? []).forEach((reservation) => {
      const date = firstMobileRecordValue(reservation, ["startAt", "createdAt"]);
      if (!date) return;
      events.push({
        id: `vehicle-reservation:${vehicle.id}:${reservation.id || date}`,
        title: vehicle.plateNumber || vehicle.name || "Rezervacija vozila",
        subtitle: [reservation.reservedForLabel, reservation.destination, reservation.purpose].filter(Boolean).join(" - "),
        status: reservation.status || "reserved",
        kind: "vehicle_reservation",
        date,
        relatedId: normalizeInputValue(vehicle.id),
        coordinates: "",
        meta: {
          vehicleName: vehicle.name || "",
          endAt: reservation.endAt || "",
        },
      });
    });
  });

  (scopedSnapshot.documentRecords ?? []).forEach((record) => {
    const date = firstMobileRecordValue(record, ["expirationDate", "validUntil", "inspectionDate", "issuedDate", "updatedAt"]);
    if (!date) return;
    events.push({
      id: `document:${record.id}`,
      title: record.title || record.documentTitle || record.templateTitle || "Dokument",
      subtitle: [record.companyName, record.locationName].filter(Boolean).join(" - "),
      status: record.status || "",
      kind: "document",
      date,
      relatedId: normalizeInputValue(record.id),
      coordinates: "",
      meta: {},
    });
  });

  (scopedSnapshot.peopleTrainingRecords ?? []).forEach((record) => {
    const trainingItems = Array.isArray(record.trainingItems) ? record.trainingItems : [];
    if (trainingItems.length === 0) {
      const date = firstMobileRecordValue(record, ["arrivalDate", "updatedAt", "createdAt"]);
      if (!date) return;
      events.push({
        id: `training:${record.id}`,
        title: record.fullName || "Osposobljavanje",
        subtitle: [record.companyName, record.jobTitle || record.workPlace].filter(Boolean).join(" - "),
        status: record.activityStatus || record.employmentStatus || "",
        kind: "training",
        date,
        relatedId: normalizeInputValue(record.id),
        coordinates: "",
        meta: {},
      });
      return;
    }

    trainingItems.forEach((item, index) => {
      const date = firstMobileRecordValue(item, ["validUntil", "certificateValidUntil", "date", "trainingDate", "createdAt"]);
      if (!date) return;
      events.push({
        id: `training:${record.id}:${item.id || index}`,
        title: item.label || item.serviceName || item.shortLabel || "Osposobljavanje",
        subtitle: [record.fullName, record.companyName, record.jobTitle || record.workPlace].filter(Boolean).join(" - "),
        status: item.status || record.activityStatus || "",
        kind: "training",
        date,
        relatedId: normalizeInputValue(record.id),
        coordinates: "",
        meta: {},
      });
    });
  });

  return events
    .sort((left, right) => String(left.date || "").localeCompare(String(right.date || "")))
    .slice(0, MOBILE_BOOTSTRAP_RECORD_LIMIT);
}

function buildMobileDashboard(scopedSnapshot = {}, workOrders = []) {
  const today = new Date().toISOString().slice(0, 10);
  const closedWorkOrders = workOrders.filter((item) => isMobileClosedWorkOrderStatus(item.status)).length;
  const overdueWorkOrders = workOrders.filter((item) => (
    !isMobileClosedWorkOrderStatus(item.status)
    && normalizeInputValue(item.dueDate).slice(0, 10) < today
    && normalizeInputValue(item.dueDate)
  )).length;

  return {
    workOrdersTotal: workOrders.length,
    activeWorkOrders: Math.max(0, workOrders.length - closedWorkOrders),
    overdueWorkOrders,
    closedWorkOrders,
    vehiclesTotal: (scopedSnapshot.vehicles ?? []).length,
    reservationsTotal: (scopedSnapshot.vehicles ?? []).reduce((total, vehicle) => (
      total + (Array.isArray(vehicle.reservations) ? vehicle.reservations.length : 0)
    ), 0),
    documentsTotal: (scopedSnapshot.documentRecords ?? []).length,
    trainingsTotal: (scopedSnapshot.peopleTrainingRecords ?? []).length,
    clientPortalTotal: (scopedSnapshot.clientPortalRecords ?? []).length,
    rulebooksTotal: (scopedSnapshot.rulebooks ?? []).length,
    riskAssessmentsTotal: (scopedSnapshot.riskAssessments ?? []).length,
    measurementEquipmentTotal: (scopedSnapshot.measurementEquipment ?? []).length,
  };
}

