      const templateId = String(body?.templateId ?? "").trim();
      const item = await saveGeneratedWorkOrderPdfDocument(workOrderPdfSaveMatch[1], workOrder, scopedSnapshot, user, templateId);
      sendJson(response, 200, { item });
